INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2716b23-c6ed-5a50-a054-9c91a318db03', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', $$An engineer enters configuration mode and makes several changes. The engineer wants to verify the changes before committing. What is the expected result?$$::text, $$[{"id": "A", "text": "The static route remains inactive until the next-hop becomes reachable.", "is_correct": false}, {"id": "B", "text": "The default action at the end of the filter is applied.", "is_correct": false}, {"id": "C", "text": "Use 'show | compare' to display differences between candidate and active config.", "is_correct": true}, {"id": "D", "text": "The packet is silently discarded.", "is_correct": false}]$$::jsonb, $$Given An engineer enters configuration mode and makes several changes. and The engineer wants to verify the changes before committing., the result is: Use 'show | compare' to display differences between candidate and active config.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$3.0 Configuration Basics$$::text, 16.67, '90e6510caeff444c', true) ON CONFLICT (id) DO NOTHING;
