INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3326aeed-52ae-5f14-9f7c-b6635d3324e4', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', $$An engineer configures a static route with next-hop 10.1.1.1. The next-hop is not reachable. What is the expected result?$$::text, $$[{"id": "A", "text": "The static route remains inactive until the next-hop becomes reachable.", "is_correct": true}, {"id": "B", "text": "Use 'commit synchronize' to apply the config to both Routing Engines.", "is_correct": false}, {"id": "C", "text": "Use 'commit confirmed' with a timeout.", "is_correct": false}, {"id": "D", "text": "The message is logged to /var/log/messages because notice is more severe than info.", "is_correct": false}]$$::jsonb, $$Given An engineer configures a static route with next-hop 10.1.1.1. and The next-hop is not reachable., the result is: The static route remains inactive until the next-hop becomes reachable.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$5.0 Routing Fundamentals$$::text, 16.67, 'ad0d0cff42ea9fb3', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30d10919-071f-5013-951f-f0a05745cf58', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', $$A packet arrives on an interface with a firewall filter. The packet does not match any term in the filter. What is the expected result?$$::text, $$[{"id": "A", "text": "Use the 'deactivate' command on the interface.", "is_correct": false}, {"id": "B", "text": "Use 'commit confirmed' with a timeout.", "is_correct": false}, {"id": "C", "text": "The message is logged to /var/log/messages because notice is more severe than info.", "is_correct": false}, {"id": "D", "text": "The default action at the end of the filter is applied.", "is_correct": true}]$$::jsonb, $$Given A packet arrives on an interface with a firewall filter. and The packet does not match any term in the filter., the result is: The default action at the end of the filter is applied.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$6.0 Routing Policy and Firewall Filters$$::text, 16.67, '8890253c82e88858', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

