INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9f5ae5eb-c374-57f9-bf8c-b7e28dbff51e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', $$An engineer wants to temporarily disable an interface configuration. The configuration should remain in the config file. What is the expected result?$$::text, $$[{"id": "A", "text": "Use the 'deactivate' command on the interface.", "is_correct": true}, {"id": "B", "text": "The then action of the first matching term is applied.", "is_correct": false}, {"id": "C", "text": "Use 'show route table inet.0' or 'show route protocol static'.", "is_correct": false}, {"id": "D", "text": "The packet is silently discarded.", "is_correct": false}]$$::jsonb, $$Given An engineer wants to temporarily disable an interface configuration. and The configuration should remain in the config file., the result is: Use the 'deactivate' command on the interface.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$3.0 Configuration Basics$$::text, 16.67, '461aab0b5fe51b25', true) ON CONFLICT (id) DO NOTHING;
