INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf7adbfd-66bd-5405-bb3d-868237fd49ee', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', $$An engineer configures 'set system syslog file messages any info'. A message with severity notice is generated. What is the expected result?$$::text, $$[{"id": "A", "text": "The default action at the end of the filter is applied.", "is_correct": false}, {"id": "B", "text": "The router uses the /26 route because it has the longest match.", "is_correct": false}, {"id": "C", "text": "The message is logged to /var/log/messages because notice is more severe than info.", "is_correct": true}, {"id": "D", "text": "The then action of the first matching term is applied.", "is_correct": false}]$$::jsonb, $$Given An engineer configures 'set system syslog file messages any info'. and A message with severity notice is generated., the result is: The message is logged to /var/log/messages because notice is more severe than info.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$4.0 Operational Monitoring and Maintenance$$::text, 16.67, '3bb8c73d93f18249', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1b382b7e-28ad-5687-a8b3-2257098bb4c0', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'single-choice', 3, 'analyze', $$A router receives a packet destined to 203.0.113.50. The routing table has 203.0.113.0/24 and 203.0.113.0/26. What is the expected result?$$::text, $$[{"id": "A", "text": "Use 'commit confirmed' with a timeout.", "is_correct": false}, {"id": "B", "text": "The router uses the /26 route because it has the longest match.", "is_correct": true}, {"id": "C", "text": "The packet is silently discarded.", "is_correct": false}, {"id": "D", "text": "Use 'show | compare' to display differences between candidate and active config.", "is_correct": false}]$$::jsonb, $$Given A router receives a packet destined to 203.0.113.50. and The routing table has 203.0.113.0/24 and 203.0.113.0/26., the result is: The router uses the /26 route because it has the longest match.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$5.0 Routing Fundamentals$$::text, 16.67, '1c14a3960ee08848', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('187c20c7-6e61-5593-ac0f-139aaf8142ea', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'simlet', 4, 'analyze', $$What happens to a directly connected route in this policy?

user@router> show configuration policy-options policy-statement EXPORT
term ACCEPT-STATIC {
    from protocol static;
    then accept;
}
term REJECT-ALL {
    then reject;
}$$::text, $$[{"id": "A", "text": "It is accepted", "is_correct": false}, {"id": "B", "text": "It is rejected by REJECT-ALL", "is_correct": true}, {"id": "C", "text": "It is accepted by default", "is_correct": false}, {"id": "D", "text": "The policy returns an error", "is_correct": false}]$$::jsonb, $$Only static routes match ACCEPT-STATIC. Directly connected routes do not match and fall through to REJECT-ALL.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$6.0 Routing Policy and Firewall Filters$$::text, 16.67, '08c4b7f52b72d49d', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('690f5a47-3c25-5cd6-8270-3fdbe37f1c70', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'simlet', 4, 'analyze', $$Which IP address is configured on ge-0/0/0.0?

