}$$::text, $$[{"id": "A", "text": "192.168.1.0/24", "is_correct": false}, {"id": "B", "text": "192.168.1.10/24", "is_correct": true}, {"id": "C", "text": "192.168.1.10/32", "is_correct": false}, {"id": "D", "text": "10.0.0.1/24", "is_correct": false}]$$::jsonb, $$The interface is configured with address 192.168.1.10/24.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$4.0 Operational Monitoring and Maintenance$$::text, 16.67, '3e2afc9f4f730b65', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

