INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('39ae737f-54cd-59c7-9a22-a34dc4d085e8', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'simlet', 4, 'analyze', $$What is the next-hop for traffic destined to 10.0.0.50?

