INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('48c960ff-db83-541a-8b0c-014777efb34e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'simlet', 4, 'analyze', $$Which next-hop is used for traffic to 10.0.0.50?

