192.168.1.0/24     user     0 192.168.1.1        ucst     5     2 ge-0/0/0.0
192.168.1.10/32    intf     0 192.168.1.10       locl     4     2 ge-0/0/0.0$$::text, $$[{"id": "A", "text": "192.168.1.10", "is_correct": false}, {"id": "B", "text": "192.168.1.1", "is_correct": true}, {"id": "C", "text": "10.0.0.1", "is_correct": false}, {"id": "D", "text": "default", "is_correct": false}]$$::jsonb, $$The forwarding table shows 10.0.0.0/24 uses next-hop 192.168.1.1.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$5.0 Routing Fundamentals$$::text, 16.67, 'b5e62bc6a6017fe9', true) ON CONFLICT (id) DO NOTHING;
