INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6c9ebef-7416-577b-866c-8d4763db640e', 'b0000000-0000-0000-0000-000000000001', 'a0000000-0000-0000-0000-000000000001', 'multiple-choice', 3, 'analyze', $$Which actions can be used in a routing policy then statement? (Choose two.)$$::text, $$[{"id": "A", "text": "permit", "is_correct": false}, {"id": "B", "text": "drop", "is_correct": false}, {"id": "C", "text": "accept", "is_correct": true}, {"id": "D", "text": "reject", "is_correct": true}, {"id": "E", "text": "forward", "is_correct": false}]$$::jsonb, $$Routing policy actions include accept, reject, next policy, and next term. Forward/drop are firewall filter actions.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncia-junos.html"}$$::text[], $$6.0 Routing Policy and Firewall Filters$$::text, 16.67, '18c5ab8d892d6315', true) ON CONFLICT (id) DO NOTHING;
